macro_rules! corpus_test {
    ($name:ident, $dir:literal) => {
        #[test]
        fn $name() {
            TestCase::new($dir).run();
        }
    };
    ($name:ident, $dir:literal, max_mismatches = $n:expr) => {
        #[test]
        fn $name() {
            let base = PathBuf::from("wdb_files/wdbcvt-waveforms/hdl/corpus");
            let dir = base.join($dir);
            TestCase {
                wdb_path: dir.join("sim.wdb"),
                fst_path: dir.join("sim.fst"),
                max_mismatches: $n,
            }
            .run();
        }
    };
}

