#[test]
fn test_open_simple_vhdl() {
    let wdb =
        WdbFile::open("wdb_files/wdbcvt-waveforms/hdl/corpus/t6_var_int______/sim.wdb")
            .expect("open WDB");
    let hier = wdb.hierarchy();
    let root = hier.root();
    assert_eq!(hier.scope(root).name, "_top");
    assert!(!hier.child_scopes(root).is_empty(), "root should have children");
    assert_eq!(wdb.time_unit().exponent, -12);
}

#[test]
fn test_signal_load_simple() {
    let mut wdb =
        WdbFile::open("wdb_files/wdbcvt-waveforms/hdl/corpus/t6_var_int______/sim.wdb")
            .expect("open WDB");
    wdb.load_all_signals().expect("load signals");

    let hier = wdb.hierarchy();
    let var_ref = hier.find_var("_top.tb.s").expect("find _top.tb.s");
    let sid = hier.var(var_ref).signal_id.expect("tb.s should have signal ID");
    let changes = wdb.signal_changes(sid).expect("should have value changes");
    assert!(!changes.is_empty(), "tb.s should have value changes");
}

#[test]
fn test_selective_signal_load() {
    let mut wdb =
        WdbFile::open("wdb_files/wdbcvt-waveforms/hdl/corpus/t6_var_int______/sim.wdb")
            .expect("open WDB");

    let hier = wdb.hierarchy();
    let s_ref = hier.find_var("_top.tb.s").expect("find _top.tb.s");
    let s_sid = hier.var(s_ref).signal_id.unwrap();
    let v_ref = hier.find_var("_top.tb.p.v").expect("find _top.tb.p.v");
    let v_sid = hier.var(v_ref).signal_id.unwrap();

    // Load only tb.s.
    wdb.load_signals(&[s_sid]).expect("load s");
    assert!(wdb.signal_changes(s_sid).map(|c| !c.is_empty()).unwrap_or(false));
    // tb.p.v should not be loaded yet.
    assert!(wdb.signal_changes(v_sid).is_none());
}

#[test]
fn test_hierarchy_walk() {
    let wdb =
        WdbFile::open("wdb_files/wdbcvt-waveforms/hdl/corpus/t19_v_wor_______/sim.wdb")
            .expect("open WDB");
    let hier = wdb.hierarchy();
    let mut scope_names: Vec<String> = Vec::new();
    hier.walk_scopes(|_, scope| scope_names.push(scope.name.clone()));
    assert!(scope_names.contains(&"_top".to_string()));
    assert!(scope_names.contains(&"tb".to_string()));
}

#[test]
fn test_scopes_in_vars_in() {
    let wdb =
        WdbFile::open("wdb_files/wdbcvt-waveforms/hdl/corpus/t53_inst3_empty_/sim.wdb")
            .expect("open WDB");
    let hier = wdb.hierarchy();

    // scopes_in(None) → top-level scopes (children of _top).
    let top_scopes = hier.scopes_in(None);
    assert!(!top_scopes.is_empty(), "should have top-level scopes");
    let top_names: Vec<&str> = top_scopes.iter().map(|&sr| hier.scope(sr).name.as_str()).collect();
    assert!(top_names.contains(&"tb"), "tb should be a top-level scope");

    // scopes_in(Some(tb)) → children of tb (d0, d1, d2, p).
    let tb_ref = hier.find_scope("_top.tb").expect("find tb");
    let tb_children = hier.scopes_in(Some(tb_ref));
    assert!(tb_children.len() >= 3, "tb should have at least d0, d1, d2");

    // vars_in(Some(tb)) → tb.s
    let tb_vars = hier.vars_in(Some(tb_ref));
    let tb_var_names: Vec<&str> = tb_vars.iter().map(|&vr| hier.var(vr).name.as_str()).collect();
    assert!(tb_var_names.contains(&"s"), "tb should have signal s");
}

#[test]
fn test_type_table_parsed() {
    let wdb =
        WdbFile::open("wdb_files/wdbcvt-waveforms/hdl/corpus/t6_var_int______/sim.wdb")
            .expect("open WDB");
    assert!(!wdb.hierarchy().types.is_empty(), "type table should not be empty");
}

#[test]
fn test_var_by_signal_id_roundtrip() {
    let wdb =
        WdbFile::open("wdb_files/wdbcvt-waveforms/hdl/corpus/t6_var_int______/sim.wdb")
            .expect("open WDB");
    let hier = wdb.hierarchy();
    let vr = hier.find_var("_top.tb.s").unwrap();
    let sid = hier.var(vr).signal_id.unwrap();
    let found = hier.var_by_signal_id(sid).expect("reverse lookup should work");
    assert_eq!(found, vr);
}
